using System.Text;
using GestionMagasin.Domain;
using Microsoft.Data.Sqlite;

namespace GestionMagasin.Infrastructure;

public sealed class SqliteReportingRepository(SqliteConnectionFactory factory) : IReportingRepository
{
    public async Task<DashboardMetrics> DashboardAsync(Utilisateur actor,DateTime day,string zoneId,CancellationToken ct=default){var (from,to)=Bounds(day,zoneId);await using var c=factory.Create();var sql="SELECT COALESCE(SUM(v.TotalFcfa),0),COUNT(DISTINCT v.Id),COALESCE(SUM(l.Quantite),0) FROM Vente v LEFT JOIN LigneVente l ON l.VenteId=v.Id WHERE v.Statut='VALIDEE' AND v.DateTechniqueUtc >= $from AND v.DateTechniqueUtc < $to AND ($admin=1 OR v.UtilisateurId=$uid)";await using var cmd=c.CreateCommand();cmd.CommandText=sql;cmd.Parameters.AddWithValue("$from",from);cmd.Parameters.AddWithValue("$to",to);cmd.Parameters.AddWithValue("$admin",actor.Role==Roles.Administrateur?1:0);cmd.Parameters.AddWithValue("$uid",actor.Id.ToString());await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var sales=r.GetInt64(0);var count=r.GetInt32(1);var units=r.GetInt32(2);await using var alerts=c.CreateCommand();alerts.CommandText="SELECT SUM(CASE WHEN stock<=0 THEN 1 ELSE 0 END),SUM(CASE WHEN stock>0 AND stock<=seuil THEN 1 ELSE 0 END) FROM (SELECT p.SeuilAlerte seuil,COALESCE((SELECT SUM(Quantite) FROM MouvementStock m WHERE m.ProduitId=p.Id),0) stock FROM Produit p WHERE p.Actif=1)";await using var ar=await alerts.ExecuteReaderAsync(ct);await ar.ReadAsync(ct);return new DashboardMetrics(day,sales,count,units,Convert.ToInt32(ar.IsDBNull(0)?0:ar.GetInt64(0)),Convert.ToInt32(ar.IsDBNull(1)?0:ar.GetInt64(1)));}
    public async Task<IReadOnlyList<RapportProduit>> VentesParProduitAsync(Utilisateur actor,DateTime fromDay,DateTime toDay,string zoneId,CancellationToken ct=default){var (from,to)=Bounds(fromDay,zoneId,Bounds(toDay,zoneId).To);await using var c=factory.Create();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT l.ReferenceSnapshot,l.NomSnapshot,SUM(l.Quantite),SUM(l.Quantite*l.PrixUnitaireFcfa) FROM LigneVente l JOIN Vente v ON v.Id=l.VenteId WHERE v.Statut='VALIDEE' AND v.DateTechniqueUtc >= $from AND v.DateTechniqueUtc < $to AND ($admin=1 OR v.UtilisateurId=$uid) GROUP BY l.ProduitId,l.ReferenceSnapshot,l.NomSnapshot ORDER BY l.NomSnapshot";cmd.Parameters.AddWithValue("$from",from);cmd.Parameters.AddWithValue("$to",to);cmd.Parameters.AddWithValue("$admin",actor.Role==Roles.Administrateur?1:0);cmd.Parameters.AddWithValue("$uid",actor.Id.ToString());var list=new List<RapportProduit>();await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new RapportProduit(r.GetString(0),r.GetString(1),r.GetInt32(2),r.GetInt64(3)));return list;}
    public async Task<RapportSynthese> SyntheseAsync(Utilisateur actor,DateTime fromDay,DateTime toDay,string zoneId,CancellationToken ct=default){var rows=await VentesParProduitAsync(actor,fromDay,toDay,zoneId,ct);var sales=await CountSalesAsync(actor,fromDay,toDay,zoneId,ct);return new RapportSynthese(sales,rows.Sum(x=>x.UnitesVendues),rows.Sum(x=>x.MontantFcfa));}
    async Task<int> CountSalesAsync(Utilisateur actor,DateTime fromDay,DateTime toDay,string zoneId,CancellationToken ct){var (from,to)=Bounds(fromDay,zoneId,Bounds(toDay,zoneId).To);await using var c=factory.Create();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(*) FROM Vente WHERE Statut='VALIDEE' AND DateTechniqueUtc >= $from AND DateTechniqueUtc < $to AND ($admin=1 OR UtilisateurId=$uid)";cmd.Parameters.AddWithValue("$from",from);cmd.Parameters.AddWithValue("$to",to);cmd.Parameters.AddWithValue("$admin",actor.Role==Roles.Administrateur?1:0);cmd.Parameters.AddWithValue("$uid",actor.Id.ToString());return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct));}
    public async Task<IReadOnlyList<MouvementStockDto>> StockAsync(CancellationToken ct=default){var repo=new SqliteStockRepository(factory);return await repo.ListerAsync(null,ct);}
    static (string From,string To) Bounds(DateTime day,string zoneId,string? explicitTo=null){var zone=TimeZoneInfo.FindSystemTimeZoneById(zoneId);var from=TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(day.Date,DateTimeKind.Unspecified),zone);var to=explicitTo??TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(day.Date.AddDays(1),DateTimeKind.Unspecified),zone).ToString("O");return(from.ToString("O"),to);}
}

public sealed class SqliteSettingsRepository(SqliteConnectionFactory factory) : ISettingsRepository
{
    public async Task<ParametresMagasin> ObtenirAsync(CancellationToken ct=default){await using var c=factory.Create();return new ParametresMagasin(await Get(c,"nom_commercial","Gestion Magasin",ct),await Get(c,"coordonnees","",ct),await GetNullable(c,"logo_path",ct),await Get(c,"devise","FCFA",ct),await Get(c,"fuseau_horaire",TimeZoneInfo.Local.Id,ct),await Get(c,"politique_sauvegarde","Quotidienne - 7 sauvegardes",ct));}
    public async Task EnregistrerAsync(ParametresMagasin p,CancellationToken ct=default){await using var c=factory.Create();foreach(var item in new[]{("nom_commercial",p.NomCommercial),("coordonnees",p.Coordonnees),("logo_path",p.LogoPath??""),("devise",p.Devise),("fuseau_horaire",p.FuseauHoraire),("politique_sauvegarde",p.PolitiqueSauvegarde)}){await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Parametre(Cle,Valeur,ModifieLeUtc) VALUES($k,$v,$d) ON CONFLICT(Cle) DO UPDATE SET Valeur=excluded.Valeur,ModifieLeUtc=excluded.ModifieLeUtc";cmd.Parameters.AddWithValue("$k",item.Item1);cmd.Parameters.AddWithValue("$v",item.Item2);cmd.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));await cmd.ExecuteNonQueryAsync(ct);}}
    static async Task<string> Get(SqliteConnection c,string key,string fallback,CancellationToken ct){var v=await GetNullable(c,key,ct);return string.IsNullOrEmpty(v)?fallback:v;}
    static async Task<string?> GetNullable(SqliteConnection c,string key,CancellationToken ct){await using var cmd=c.CreateCommand();cmd.CommandText="SELECT Valeur FROM Parametre WHERE Cle=$k";cmd.Parameters.AddWithValue("$k",key);return await cmd.ExecuteScalarAsync(ct) as string;}
}

public sealed class SqliteAuditWriter(SqliteConnectionFactory factory) : IAuditWriter
{
    public async Task EcrireAsync(AuditEntry e,CancellationToken ct=default){await using var c=factory.Create();await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO JournalAudit(Id,UtilisateurId,Action,Entite,EntiteId,Details,DateTechniqueUtc) VALUES($id,$u,$a,$e,$eid,$d,$date)";cmd.Parameters.AddWithValue("$id",e.Id.ToString());cmd.Parameters.AddWithValue("$u",(object?)e.UtilisateurId?.ToString()??DBNull.Value);cmd.Parameters.AddWithValue("$a",e.Action);cmd.Parameters.AddWithValue("$e",e.Entite);cmd.Parameters.AddWithValue("$eid",(object?)e.EntiteId?.ToString()??DBNull.Value);cmd.Parameters.AddWithValue("$d",(object?)e.Details??DBNull.Value);cmd.Parameters.AddWithValue("$date",e.DateUtc.ToUniversalTime().ToString("O"));await cmd.ExecuteNonQueryAsync(ct);}
}

public sealed class SqliteBackupManager(SqliteConnectionFactory factory) : IBackupManager
{
    public async Task<SauvegardeInfo> SauvegarderAsync(string destination,string type,Guid? user,CancellationToken ct=default){Directory.CreateDirectory(Path.GetDirectoryName(destination)!);var id=Guid.NewGuid();try{await using var source=factory.Create();await using var target=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=destination,Mode=SqliteOpenMode.ReadWriteCreate}.ToString());await target.OpenAsync(ct);source.BackupDatabase(target);var info=new SauvegardeInfo(id,destination,DateTime.UtcNow,type,true,null);await RecordAsync(info,ct);return info;}catch(Exception ex){var info=new SauvegardeInfo(id,destination,DateTime.UtcNow,type,false,ex.Message);await RecordAsync(info,ct);throw;}}
    public async Task VerifierAsync(string source,CancellationToken ct=default){await using var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=source,Mode=SqliteOpenMode.ReadOnly}.ToString());await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="PRAGMA integrity_check";if(Convert.ToString(await cmd.ExecuteScalarAsync(ct))!="ok")throw new DomainException("La sauvegarde est corrompue.");await using var schema=c.CreateCommand();schema.CommandText="SELECT COUNT(*) FROM VersionSchema";if(Convert.ToInt32(await schema.ExecuteScalarAsync(ct))==0)throw new DomainException("Schéma incompatible.");}
    public async Task RestaurerAsync(string source,CancellationToken ct=default){await VerifierAsync(source,ct);var previous=factory.DatabasePath+".before-restore-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss")+".db";if(File.Exists(factory.DatabasePath))File.Copy(factory.DatabasePath,previous);try{File.Copy(source,factory.DatabasePath,true);await VerifierAsync(factory.DatabasePath,ct);}catch{if(File.Exists(previous))File.Copy(previous,factory.DatabasePath,true);throw;}}
    async Task RecordAsync(SauvegardeInfo i,CancellationToken ct){await using var c=factory.Create();await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Sauvegarde(Id,Chemin,DateUtc,Type,Succes,Message) VALUES($id,$p,$d,$t,$s,$m)";cmd.Parameters.AddWithValue("$id",i.Id.ToString());cmd.Parameters.AddWithValue("$p",i.Chemin);cmd.Parameters.AddWithValue("$d",i.DateUtc.ToString("O"));cmd.Parameters.AddWithValue("$t",i.Type);cmd.Parameters.AddWithValue("$s",i.Succes?1:0);cmd.Parameters.AddWithValue("$m",(object?)i.Message??DBNull.Value);await cmd.ExecuteNonQueryAsync(ct);}
    public async Task EnsureDailyAsync(CancellationToken ct=default){var dir=Path.Combine(Path.GetDirectoryName(factory.DatabasePath)!,"backups");Directory.CreateDirectory(dir);var path=Path.Combine(dir,$"gestion-magasin-{DateTime.UtcNow:yyyyMMdd}.db");if(!File.Exists(path))await SauvegarderAsync(path,"AUTOMATIQUE",null,ct);foreach(var file in new DirectoryInfo(dir).GetFiles("*.db").OrderByDescending(x=>x.CreationTimeUtc).Skip(7))file.Delete();}
}

public static class CsvExporter
{
    public static async Task ExportAsync(string path,IEnumerable<string> headers,IEnumerable<IEnumerable<object?>> rows,CancellationToken ct=default){Directory.CreateDirectory(Path.GetDirectoryName(path)!);await using var stream=File.Create(path);await using var writer=new StreamWriter(stream,new UTF8Encoding(true));await writer.WriteLineAsync(string.Join(";",headers.Select(Escape)));foreach(var row in rows)await writer.WriteLineAsync(string.Join(";",row.Select(x=>Escape(Convert.ToString(x,System.Globalization.CultureInfo.InvariantCulture)??""))));}
    static string Escape(string value){if(value.Length>0&&"=+-@".Contains(value[0]))value="'"+value;return '"'+value.Replace("\"","\"\"")+'"';}
}
